  "evaluation_id": "eval-384c05531c9023b792847f3224cc60b0",
  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 1,
          "line_end": 1,
          "quote": "**Plano de Aula: Requisitos Funcionais e Não Funcionais de um Sistema de Biblioteca**"
        }
      ],
      "justification": "O plano contempla requisitos funcionais e não funcionais, situados explicitamente em um sistema de biblioteca."
    },
    "grade_level": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 8,
          "line_end": 9,
          "quote": "- **Cursos:** Graduação em Ciência da Computação  \n- **Turma:** Introductory  "
        }
      ],
      "justification": "Estão explícitos tanto o curso de graduação em Ciência da Computação quanto o caráter introdutório da formação."
    },
    "learning_objectives": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 11,
          "line_end": 12,
          "quote": "- **Objetivo de Aprendizagem:**  \n  Identificar e especificar **dois requisitos funcionais** e **dois requisitos não funcionais** de um sistema de biblioteca, justificando a classificação e formulando condições verificáveis."
        }
      ],
      "justification": "O objetivo inclui identificar e especificar dois requisitos de cada categoria para um sistema de biblioteca, justificar sua classificação e formular condições verificáveis."
    },
    "duration_minutes": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 10,
          "line_end": 10,
          "quote": "- **Duração:** 50 minutos  "
        },
        {
          "line_start": 37,
          "line_end": 41,
          "quote": "| 0–5 min | Apresentação do objetivo da aula e explicação breve dos conceitos de requisitos funcionais e não funcionais. |\n| 5–15 min | Distribuição dos materiais e orientação para a resolução colaborativa. |\n| 15–35 min | Trabalho em grupos: identificação, classificação, justificação e formulação de condições de verificação dos requisitos. |\n| 35–45 min | Apresentação oral dos grupos (cada grupo apresenta 2 requisitos funcionais e 2 não funcionais). |\n| 45–50 min | Discussão coletiva, feedback entre os grupos, e encerramento da aula com resumo dos conceitos principais. |"
        }
      ],
      "justification": "A duração declarada é de 50 minutos e o cronograma apresenta intervalos consecutivos, sem sobreposição, de 0 a 50 minutos."
    },
    "methodology": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 16,
          "line_end": 18,
          "quote": "### **2. Metodologia: Resolução Colaborativa de Problemas**\n\n- **Descrição:** Os alunos trabalharão em grupos de 3 a 4 pessoas, utilizando um **quadro de descrição de sistema** e uma **folha com um exemplo de sistema de empréstimo de biblioteca** como recursos."
        },
        {
          "line_start": 39,
          "line_end": 39,
          "quote": "| 15–35 min | Trabalho em grupos: identificação, classificação, justificação e formulação de condições de verificação dos requisitos. |"
        }
      ],
      "justification": "A resolução colaborativa de problemas é declarada e concretizada no trabalho em grupos para identificar, classificar, justificar e formular condições de verificação de requisitos."
    },
    "materials": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 18,
          "line_end": 18,
          "quote": "- **Descrição:** Os alunos trabalharão em grupos de 3 a 4 pessoas, utilizando um **quadro de descrição de sistema** e uma **folha com um exemplo de sistema de empréstimo de biblioteca** como recursos."
        },
        {
          "line_start": 26,
          "line_end": 27,
          "quote": "- **Quadro com descrição de sistema de empréstimo de biblioteca** (exemplo de sistema com funções e comportamentos).  \n- **Folha de atividade** com perguntas e diretrizes.  "
        }
      ],
      "justification": "O quadro está previsto expressamente. A folha com um exemplo do sistema de empréstimo de biblioteca também é explicitada na descrição da metodologia, embora a lista de materiais a descreva de maneira mais geral como folha de atividade."
    },
    "assessment_strategy": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 85,
          "line_end": 86,
          "quote": "- Cada grupo apresentará 2 requisitos funcionais e 2 não funcionais, com justificativa e condições de verificação.\n- A avaliação será baseada na **precisão da classificação**, na **justificativa** e na **condição de verificação**."
        }
      ],
      "justification": "A apresentação dos grupos constitui a entrega dos dois requisitos funcionais e dois não funcionais. São exigidas justificativas de classificação e condições de verificação para os requisitos apresentados, e esses componentes são explicitados como critérios de avaliação."
    }
  },
  "assessments": {
